261	
262	    /**
263	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
264	     * stripped. When a leading {@code '+'} and country code are present they are kept;
265	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
266	     * is dropped from the national digits. The result must be a {@code '+'} followed
267	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
268	     * is returned to signal a bad request.
269	     */
270	    /**
271	     * Build the customer code for a newly created owner, formatted
272	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
273	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
274	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
275	     * one more than the number of owners already in that city.
276	     */
277	    private String nextCustomerCode(String city, String lastName) {
278	        String cityPrefix = prefixThree(city);
279	        String lastNamePrefix = prefixThree(lastName);
280	        String normalizedCity = normalizeForHousehold(city);
281	        int sequence = (int) this.clinicService.findAllOwners().stream()
282	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
283	            .count() + 1;
284	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
285	    }
286	
287	    /**
288	     * Count the existing owners whose city matches the given one, compared after
289	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
290	     * cap: a city that already holds this many owners is at capacity.
291	     */
292	    private long countOwnersInCity(String city) {
293	        String normalizedCity = normalizeForHousehold(city);
294	        return this.clinicService.findAllOwners().stream()
295	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
296	            .count();
297	    }
298	
299	    /**
300	     * Count the existing owners whose registration date falls on the given day. Used to
301	     * enforce the per-day create limit: once this many owners have been registered today,
302	     * the day is at capacity and further creates are rejected.
303	     */
304	    private long countOwnersRegisteredOn(LocalDate day) {
305	        return this.clinicService.findAllOwners().stream()
306	            .filter(existing -> day.equals(existing.getRegistrationDate()))
307	            .count();
308	    }
309	
310	    /**
311	     * Roll a registration date forward to the next business day: a date falling on a
312	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
313	     * returned unchanged.
314	     */
315	    private LocalDate toBusinessDay(LocalDate date) {
316	        DayOfWeek dayOfWeek = date.getDayOfWeek();
317	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
318	            return date.plusDays(8 - dayOfWeek.getValue());
319	        }
320	        return date;
321	    }
322	
323	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
324	    private String prefixThree(String value) {
325	        String v = value == null ? "" : value;
326	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
327	    }
328	
329	    /**
330	     * Find the existing owners that already belong to the same household as the given
331	     * last name and address, i.e. those sharing both fields. Both are compared
332	     * case-insensitively after collapsing runs of whitespace to a single space and
333	     * trimming the ends.
334	     */
335	    private List<Owner> findHouseholdMembers(String lastName, String address) {
336	        String normalizedLastName = normalizeForHousehold(lastName);
337	        String normalizedAddress = normalizeForHousehold(address);
338	        return this.clinicService.findAllOwners().stream()
339	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
340	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
341	            .toList();
342	    }
343	
344	    /**
345	     * Count the existing owners that already share both the given first and last
346	     * name, compared case-insensitively. Used to populate an owner's namesake count
347	     * at creation time, reflecting how many owners with the same name existed before
348	     * this one was created.
349	     */
350	    private int countNamesakes(String firstName, String lastName) {
351	        String normalizedFirstName = normalizeName(firstName);
352	        String normalizedLastName = normalizeName(lastName);
353	        return (int) this.clinicService.findAllOwners().stream()
354	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
355	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
356	            .count();
357	    }
358	
359	    private String normalizeName(String value) {
360	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
361	    }
362	
363	    /**
364	     * Build a stable identifier shared by all owners of one household. It is derived
365	     * deterministically from the normalized last name and address, so every owner at
366	     * the same household resolves to the same value regardless of creation order.
367	     */
368	    private String householdId(String lastName, String address) {
369	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
370	        try {
371	            byte[] digest = MessageDigest.getInstance("SHA-256")
372	                .digest(key.getBytes(StandardCharsets.UTF_8));
373	            StringBuilder sb = new StringBuilder();
374	            for (int i = 0; i < 6; i++) {
375	                sb.append(String.format("%02X", digest[i]));
376	            }
377	            return "HH-" + sb;
378	        }
379	        catch (NoSuchAlgorithmException e) {
380	            throw new IllegalStateException(e);
381	        }
382	    }
383	
384	    private String normalizeForHousehold(String value) {
385	        if (value == null) {
386	            return "";
387	        }
388	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
389	    }
390	
391	    private String normalizeTelephone(String telephone) {
392	        if (telephone == null) {
393	            return null;
394	        }
395	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
396	        String digits;
397	        if (cleaned.startsWith("+")) {
398	            digits = cleaned.substring(1);
399	        } else {
400	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
401	            digits = "61" + national;
402	        }
403	        if (!digits.matches("[0-9]{8,15}")) {
404	            return null;
405	        }
406	        if (!hasValidNationalLength(digits)) {
407	            return null;
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Validate the national-number length of an E.164 number (the digits, without the
414	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
415	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
416	     * codes without a known rule are accepted as-is.
417	     */
418	    private boolean hasValidNationalLength(String digits) {
419	        if (digits.startsWith("61")) {
420	            return digits.length() - 2 == 9;
421	        }
422	        if (digits.startsWith("1")) {
423	            return digits.length() - 1 == 10;
424	        }
425	        return true;
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
431	        Owner owner = this.clinicService.findOwnerById(ownerId);
432	        if (owner != null) {
433	            Pet pet = owner.getPet(petId);
434	            if (pet != null) {
435	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
436	            }
437	        }
438	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	    }
440	}
