283	    /**
284	     * Return the owner's locality (region), preferring the postcode: when the
285	     * postcode is present and falls within a known region's inclusive range
286	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), that
287	     * region is returned. Otherwise the value falls back to the fixed
288	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
289	     * {@code Brisbane -> QLD}), or {@code 'UNKNOWN'} when the city is not in the
290	     * table. This yields the same region for known cities but disambiguates
291	     * cities that share a name.
292	     */
293	    public String getLocality() {
294	        String regionFromPostcode = regionForPostcode();
295	        if (regionFromPostcode != null) {
296	            return regionFromPostcode;
297	        }
298	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
299	    }
