301	    /**
302	     * Look up the region whose inclusive postcode range contains this owner's
303	     * postcode, or {@code null} when the postcode is absent, malformed, or in no
304	     * known range.
305	     */
306	    private String regionForPostcode() {
307	        if (this.postcode == null || !this.postcode.matches("^[0-9]{4}$")) {
308	            return null;
309	        }
310	        int value = Integer.parseInt(this.postcode);
311	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
312	            int[] range = entry.getValue();
313	            if (value >= range[0] && value <= range[1]) {
314	                return entry.getKey();
315	            }
316	        }
317	        return null;
318	    }
