330	    /**
331	     * Return the owner's derived identity key, which consolidates all duplicate
332	     * detection into a single value formed as
333	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}.
334	     * The telephone and email are already stored in their normalized (E.164 /
335	     * lower-cased) forms; a missing email or household id contributes an empty
336	     * segment. A create is rejected only when a new owner's whole identity key
337	     * equals an existing owner's.
338	     */
339	    public String getIdentityKey() {
340	        String telephonePart = this.telephone == null ? "" : this.telephone;
341	        String emailPart = (this.email == null) ? "" : this.email;
342	        String householdPart = (this.householdId == null) ? "" : this.householdId;
343	        return telephonePart + "|" + emailPart + "|" + householdPart;
344	    }
