383	     * Return the Pet with the given name, or null if none found for this Owner.
384	     *
385	     * @param name to test
386	     * @return true if pet name is already in use
387	     */
388	    public Pet getPet(String name, boolean ignoreNew) {
389	        name = name.toLowerCase();
390	        for (Pet pet : getPetsInternal()) {
391	            if (!ignoreNew || !pet.isNew()) {
392	                String compName = pet.getName();
393	                compName = compName.toLowerCase();
394	                if (compName.equals(name)) {
395	                    return pet;
396	                }
397	            }
398	        }
399	        return null;
400	    }
